// Bun entrypoint: the React Router server build behind Bun.serve. `createRequestHandler` from `react-router` is the
// runtime-agnostic Fetch API handler (Request in, Response out) that the Node/Express, Cloudflare and other adapters
// wrap; Bun.serve speaks Request/Response natively, so it is passed straight through. One Bun process.
import { createRequestHandler, type ServerBuild } from "react-router";
import { join } from "node:path";
// @ts-expect-error: generated by `react-router build`, no type declarations.
import * as serverBuild from "./build/server/index.js";

const build = serverBuild as unknown as ServerBuild;
const handler = createRequestHandler(build, process.env.NODE_ENV ?? "production");

// Client files (build/client: hashed /assets/*, favicon.ico) are immutable after the build, so they are listed once
// at startup and registered as Bun.serve static routes. Same Cache-Control as react-router-serve's express.static:
// 1 year + immutable for hashed assets, none for the rest. Page requests never touch the file system.
const clientDir = build.assetsBuildDirectory;
const routes: Record<string, Response> = {};
for await (const path of new Bun.Glob("**/*").scan({ cwd: clientDir })) {
  const file = Bun.file(join(clientDir, path));
  const headers: Record<string, string> = { "Content-Type": file.type };
  if (path.startsWith("assets/")) headers["Cache-Control"] = "public, max-age=31536000, immutable";
  routes[build.publicPath + path] = new Response(await file.bytes(), { headers });
}

const server = Bun.serve({
  hostname: process.env.HOST ?? "0.0.0.0",
  port: Number(process.env.PORT ?? 3000),
  routes,
  fetch: (request) => handler(request),
});
console.log(`react-router (bun ${Bun.version}) listening on ${server.url} (NODE_ENV=${process.env.NODE_ENV ?? "unset"})`);

// PID 1 in Docker gets SIGTERM on `docker stop`; stop the listener and exit instead of waiting for SIGKILL.
for (const signal of ["SIGTERM", "SIGINT"] as const) {
  process.on(signal, () => {
    server.stop();
    process.exit(0);
  });
}
